INSERT INTO public.services (id, title, description, price, category, icon, is_active)
VALUES
  ('10000000-0000-4000-8000-000000000001', 'كشف وإصلاح تسربات المياه', 'فحص تسربات المياه الظاهرة وإصلاح الأعطال البسيطة في التمديدات والحنفيات داخل المنزل. السعر يشمل أجرة الكشف والعمل الأساسي ولا يشمل قطع الغيار.', 20.00, 'PLUMBING', 'wrench', TRUE),
  ('10000000-0000-4000-8000-000000000002', 'تسليك مجاري ومصارف منزلية', 'تسليك مغاسل ومصارف المطابخ والحمامات باستخدام أدوات مهنية، مع فحص سبب الانسداد وتقديم إرشادات الوقاية.', 25.00, 'PLUMBING', 'droplets', TRUE),
  ('10000000-0000-4000-8000-000000000003', 'فحص أعطال الكهرباء المنزلية', 'تشخيص أعطال القواطع والمقابس والإنارة ومعالجة الأعطال الكهربائية البسيطة وفق متطلبات السلامة.', 20.00, 'ELECTRICITY', 'zap', TRUE),
  ('10000000-0000-4000-8000-000000000004', 'تركيب إنارة ومفاتيح كهربائية', 'تركيب أو استبدال وحدات الإنارة والمفاتيح والمقابس المنزلية مع اختبار التشغيل والسلامة.', 18.00, 'ELECTRICITY', 'lightbulb', TRUE),
  ('10000000-0000-4000-8000-000000000005', 'تنظيف منزل شامل', 'تنظيف شامل للغرف والمطبخ والحمامات والأرضيات والأسطح لشقة متوسطة، باستخدام مواد وأدوات تنظيف مناسبة.', 45.00, 'CLEANING', 'sparkles', TRUE),
  ('10000000-0000-4000-8000-000000000006', 'تنظيف ما بعد الانتقال أو الصيانة', 'تنظيف عميق لإزالة الغبار وآثار أعمال الصيانة وتجهيز المنزل للسكن. السعر الابتدائي لشقة متوسطة.', 65.00, 'CLEANING', 'spray-can', TRUE),
  ('10000000-0000-4000-8000-000000000007', 'صيانة وتنظيف مكيف سبليت', 'تنظيف الفلاتر والوحدة الداخلية وفحص التبريد والتصريف لمكيف سبليت واحد، دون تعبئة الغاز أو قطع الغيار.', 25.00, 'HVAC', 'snowflake', TRUE),
  ('10000000-0000-4000-8000-000000000008', 'فحص عطل تكييف وتبريد', 'زيارة تشخيصية لتحديد سبب ضعف التبريد أو توقف المكيف وتقديم تكلفة الإصلاح قبل بدء الأعمال الإضافية.', 20.00, 'HVAC', 'thermometer', TRUE),
  ('10000000-0000-4000-8000-000000000009', 'إصلاح أبواب وخزائن خشبية', 'إصلاح المفصلات والمقابض وضبط الأبواب والخزائن الخشبية ومعالجة الأعطال البسيطة في الموقع.', 25.00, 'CARPENTRY', 'hammer', TRUE),
  ('10000000-0000-4000-8000-000000000010', 'تركيب رفوف وتجهيزات خشبية', 'تركيب رفوف وتجهيزات خشبية جاهزة وتثبيتها بأمان. لا يشمل السعر المواد أو أعمال التفصيل.', 22.00, 'CARPENTRY', 'ruler', TRUE),
  ('10000000-0000-4000-8000-000000000011', 'دهان غرفة داخلية', 'تجهيز ودهان جدران غرفة متوسطة بطبقتين مع حماية الأرضيات والأثاث. السعر أجرة عمل ولا يشمل الدهان.', 55.00, 'PAINTING', 'paintbrush', TRUE),
  ('10000000-0000-4000-8000-000000000012', 'معالجة رطوبة وتقشر دهان', 'كشف أولي لمصدر الرطوبة، إزالة الأجزاء المتقشرة وتجهيز السطح للمعالجة والدهان ضمن مساحة محدودة.', 35.00, 'PAINTING', 'paint-roller', TRUE),
  ('10000000-0000-4000-8000-000000000013', 'فحص وإصلاح غسالة ملابس', 'تشخيص أعطال الغسالات المنزلية وإجراء الإصلاحات الأساسية بعد موافقة العميل على تكلفة القطع المطلوبة.', 25.00, 'APPLIANCE_REPAIR', 'washing-machine', TRUE),
  ('10000000-0000-4000-8000-000000000014', 'فحص وإصلاح ثلاجة منزلية', 'فحص أعطال التبريد والتسريب والكهرباء في الثلاجات المنزلية وتحديد تكلفة الإصلاح قبل استبدال أي قطعة.', 30.00, 'APPLIANCE_REPAIR', 'refrigerator', TRUE),
  ('10000000-0000-4000-8000-000000000015', 'تنسيق وصيانة حديقة منزلية', 'قص وتهذيب النباتات وتنظيف الحديقة وترتيب المساحات الخضراء لحديقة منزلية صغيرة أو متوسطة.', 35.00, 'GARDENING', 'leaf', TRUE),
  ('10000000-0000-4000-8000-000000000016', 'صيانة شبكة ري منزلية', 'فحص شبكة الري المنزلية وإصلاح التسريبات والمرشات البسيطة وضبط توزيع المياه.', 30.00, 'GARDENING', 'flower-2', TRUE)
